<template>
  <main class="app-shell admin-shell">
    <header class="topbar"><div class="topbar-brand"><BrandLogo variant="main" compact link /><span class="slash">/</span><span class="section-name">{{ t('nav.admin') }}</span></div><div class="topbar-actions"><LanguageSelect :user="sessionUser" /><RouterLink to="/" class="icon-text-button"><FolderOpen :size="16" /> {{ t('nav.files') }}</RouterLink><RouterLink to="/logs" class="icon-text-button"><ScrollText :size="16" /> {{ t('nav.logs') }}</RouterLink><RouterLink to="/change-password?mode=self" class="icon-button" :title="t('nav.changePassword')"><KeyRound :size="17" /></RouterLink><button class="icon-button" :title="t('nav.logout')" @click="logout"><LogOut :size="18" /></button></div></header>
    <section class="admin-layout">
      <aside class="admin-sidebar">
        <button v-for="tab in tabs" :key="tab.key" class="admin-tab" :class="{ active: activeTab === tab.key }" @click="switchTab(tab.key)"><component :is="tab.icon" :size="17" /><span>{{ t(tab.label) }}</span></button>
      </aside>
      <section class="content-wrap admin-content">
        <div class="page-heading"><div><p class="eyebrow">{{ t('admin.eyebrow') }}</p><h1>{{ t('admin.heading') }}</h1><p class="muted">{{ t('admin.copy') }}</p></div></div>
        <div v-if="error" class="alert error">{{ error }}</div><div v-if="notice" class="alert success">{{ notice }}</div>

        <div v-show="activeTab === 'overview'">
          <div class="stats-grid"><div class="stat-block"><span>{{ t('admin.userCount') }}</span><strong>{{ stats.users ?? '-' }}</strong><Users :size="20" /></div><div class="stat-block"><span>{{ t('admin.fileCount') }}</span><strong>{{ stats.files ?? '-' }}</strong><Files :size="20" /></div><div class="stat-block"><span>{{ t('admin.usedSpace') }}</span><strong>{{ formatBytes(stats.bytes || 0) }}</strong><HardDrive :size="20" /></div><div class="stat-block"><span>{{ t('admin.shares') }}</span><strong>{{ stats.shares ?? '-' }}</strong><small class="stat-subvalue">{{ t('admin.shareDownloads') }}: {{ stats.shareDownloads ?? 0 }}</small><Share2 :size="20" /></div><div class="stat-block disk-stat" :class="{ 'disk-warning': (stats.disk?.usagePercent ?? 0) >= 90 }"><span>{{ t('admin.diskUsage') }}</span><strong>{{ formatBytes(stats.disk?.used || 0) }} / {{ formatBytes(stats.disk?.total || 0) }}</strong><div class="disk-stat-meta">{{ stats.disk?.usagePercent ?? '-' }}%</div><div class="progress-track disk-progress"><span :style="{ width: `${Math.min(100, stats.disk?.usagePercent || 0)}%` }"></span></div><HardDrive :size="20" /></div></div>
          <div class="form-panel"><div class="panel-heading"><div><p class="eyebrow">{{ t('admin.systemLanguage') }}</p><h2>{{ t('admin.systemLanguage') }}</h2><p class="muted">{{ t('admin.systemLanguageCopy') }}</p></div><div class="settings-control"><select v-model="settings.defaultLang" :aria-label="t('admin.systemLanguage')"><option value="zh-CN">{{ t('lang.zhCN') }}</option><option value="zh-TW">{{ t('lang.zhTW') }}</option><option value="en">{{ t('lang.en') }}</option></select><button class="secondary-button" :disabled="settingsSaving" @click="saveSettings"><Save :size="16" /> {{ t('admin.saveSettings') }}</button></div></div></div>
        </div>

        <div v-show="activeTab === 'users'">
          <div class="toolbar admin-toolbar"><button class="primary-button" @click="openCreate"><UserPlus :size="17" /> {{ t('admin.createUser') }}</button><div class="search-box"><Search :size="17" /><input v-model="searchInput" :placeholder="t('admin.searchPlaceholder')" @keyup.enter="loadUsers" /></div><button class="refresh-button" :title="t('admin.refresh')" @click="loadAll"><RefreshCw :size="17" :class="{ spin: loading }" /></button><span class="result-count">{{ t('common.accounts', { count: total }) }}</span></div>
          <div class="user-table-wrap"><table class="file-table user-table"><thead><tr><th>{{ t('admin.user') }}</th><th>{{ t('admin.role') }}</th><th>{{ t('admin.folderCount') }}</th><th>{{ t('admin.fileCount') }}</th><th>{{ t('admin.space') }}</th><th>{{ t('admin.status') }}</th><th>{{ t('admin.createdAt') }}</th><th></th></tr></thead><tbody><tr v-for="item in users" :key="item.id"><td><div class="user-cell"><span class="avatar">{{ item.username.slice(0, 1).toUpperCase() }}</span><strong>{{ item.username }}</strong></div></td><td><span class="role-label" :class="item.role">{{ item.role === 'admin' ? t('admin.adminRole') : t('admin.userRole') }}</span></td><td>{{ item.folderCount ?? 0 }}</td><td>{{ item.fileCount ?? 0 }}</td><td><div class="user-quota"><span>{{ formatBytes(item.usedBytes) }} / {{ formatBytes(item.quotaBytes) }}</span><div class="progress-track"><span :style="{ width: `${Math.min(100, item.quotaBytes ? item.usedBytes / item.quotaBytes * 100 : 0)}%` }"></span></div></div></td><td><span class="status-label" :class="{ disabled: item.disabled }"><i></i>{{ item.disabled ? t('admin.disabled') : t('admin.normal') }}</span></td><td>{{ formatDate(item.createdAt) }}</td><td><div class="row-actions"><button class="icon-button" :title="t('admin.editUser')" @click="edit(item)"><Pencil :size="17" /></button><button class="icon-button danger-icon" :title="t('admin.deleteUser')" @click="remove(item)"><Trash2 :size="17" /></button></div></td></tr></tbody></table><div v-if="!loading && !users.length" class="empty-state"><Users :size="34" /><strong>{{ t('admin.noUsers') }}</strong></div><div v-if="loading" class="empty-state"><LoaderCircle :size="28" class="spin" /><span>{{ t('common.loading') }}</span></div></div>
        </div>

        <div v-show="activeTab === 'security'">
          <div class="form-panel security-settings"><div class="panel-heading"><div><p class="eyebrow">{{ t('admin.securityEyebrow') }}</p><h2>{{ t('admin.securityHeading') }}</h2><p class="muted">{{ t('admin.securityCopy') }}</p></div><button class="secondary-button" :disabled="settingsSaving" @click="saveSettings"><Save :size="16" /> {{ t('admin.saveSettings') }}</button></div><div class="security-grid"><label>{{ t('admin.passwordMinLength') }}<input v-model.number="settings.passwordMinLength" type="number" min="1" max="200" /></label><label>{{ t('admin.passwordComplexity') }}<input v-model.number="settings.passwordComplexity" type="number" min="0" max="4" /></label><label>{{ t('admin.ipLockWindow') }}<input v-model.number="settings.ipLockWindowMinutes" type="number" min="1" /><span>{{ t('common.minutes') }}</span></label><label>{{ t('admin.ipLockThreshold') }}<input v-model.number="settings.ipLockThreshold" type="number" min="0" /><span>{{ t('common.zeroDisabled') }}</span></label><label class="check-label"><input v-model="settings.ipAutoUnlockEnabled" type="checkbox" /> {{ t('admin.ipAutoUnlock') }}</label><label>{{ t('admin.ipUnlockMinutes') }}<input v-model.number="settings.ipUnlockMinutes" type="number" min="1" /><span>{{ t('common.minutes') }}</span></label></div></div>
        </div>

        <div v-show="activeTab === 'brand'">
          <div class="form-panel brand-panel"><div class="panel-heading"><div><p class="eyebrow">{{ t('admin.brandEyebrow') }}</p><h2>{{ t('admin.brandHeading') }}</h2><p class="muted">{{ t('admin.brandCopy') }}</p></div><BrandLogo variant="main" compact /></div><form class="brand-form" @submit.prevent="saveBrand"><label>{{ t('admin.siteTitle') }}<div class="field-with-action"><input v-model.trim="brandForm.siteTitle" maxlength="64" /><button type="button" class="icon-button" :title="t('admin.clearField', { field: t('admin.siteTitle') })" @click="clearText('siteTitle')"><X :size="16" /></button></div></label><label>{{ t('admin.siteDescription') }}<div class="field-with-action"><textarea v-model.trim="brandForm.siteDescription" maxlength="200" rows="2"></textarea><button type="button" class="icon-button" :title="t('admin.clearField', { field: t('admin.siteDescription') })" @click="clearText('siteDescription')"><X :size="16" /></button></div></label><label>{{ t('admin.icp') }}<div class="field-with-action"><input v-model.trim="brandForm.icpText" maxlength="128" /><button type="button" class="icon-button" :title="t('admin.clearField', { field: t('admin.icp') })" @click="clearText('icpText')"><X :size="16" /></button></div></label><label>{{ t('admin.police') }}<div class="field-with-action"><input v-model.trim="brandForm.policeText" maxlength="128" /><button type="button" class="icon-button" :title="t('admin.clearField', { field: t('admin.police') })" @click="clearText('policeText')"><X :size="16" /></button></div></label><label>{{ t('admin.copyright') }}<div class="field-with-action"><input v-model.trim="brandForm.copyrightText" maxlength="128" :placeholder="t('admin.copyrightPlaceholder')" /><button type="button" class="icon-button" :title="t('admin.clearField', { field: t('admin.copyright') })" @click="clearText('copyrightText')"><X :size="16" /></button></div></label><label class="theme-color-field">{{ t('admin.themeColor') }}<div class="theme-color-control"><input v-model.trim="brandForm.themeColor" class="theme-color-input" :class="{ invalid: themeColorInvalid }" maxlength="7" :aria-invalid="themeColorInvalid" placeholder="#RRGGBB" spellcheck="false" /><input class="theme-color-picker" type="color" :value="themeColorPicker" :aria-label="t('admin.themeColor')" @input="selectThemeColor" /><button type="button" class="secondary-button" @click="resetThemeColor"><RefreshCw :size="15" /> {{ t('admin.resetThemeColor') }}</button></div><span v-if="themeColorInvalid" class="field-error">{{ t('error.invalidThemeColor') }}</span></label><div v-for="asset in brandAssetFields" :key="asset.key" class="brand-asset-field"><span class="brand-field-label">{{ t(asset.labelKey) }}</span><div class="brand-asset-row"><img :src="asset.preview" :alt="t(asset.labelKey)" /><div><input type="file" :accept="asset.accept" @change="selectBrandFile(asset, $event)" /><span class="brand-file-note">{{ asset.pendingRemove ? t('admin.removeAfterSave') : asset.file?.name || (asset.hasCustom ? t('admin.customAsset') : t('admin.defaultAsset')) }}</span></div><button v-if="asset.hasCustom || asset.file" type="button" class="icon-button danger-icon" :title="t('admin.removeAsset')" @click="removeBrandFile(asset)"><Trash2 :size="16" /></button></div></div><div class="brand-actions"><button class="primary-button" :disabled="brandSaving || themeColorInvalid"><Save :size="16" /> {{ t('admin.saveBrand') }}</button><button type="button" class="secondary-button" :disabled="brandSaving" @click="resetBrand"><RefreshCw :size="16" /> {{ t('admin.resetBrand') }}</button></div></form></div>
        </div>

        <div v-show="activeTab === 'locks'">
          <div class="form-panel locks-panel"><div class="panel-heading"><div><p class="eyebrow">{{ t('admin.locksEyebrow') }}</p><h2>{{ t('admin.locksHeading') }}</h2><p class="muted">{{ t('admin.locksCopy') }}</p></div><button class="refresh-button" :title="t('admin.refreshLocks')" @click="loadLocks"><RefreshCw :size="17" /></button></div><div class="lock-tables"><div><h3>{{ t('admin.ipLocks') }}</h3><table class="file-table"><thead><tr><th>{{ t('admin.ip') }}</th><th>{{ t('admin.failedCount') }}</th><th>{{ t('admin.lockedUntil') }}</th><th></th></tr></thead><tbody><tr v-for="lock in ipLocks" :key="lock.ip"><td>{{ lock.ip }}</td><td>{{ lock.failedCount }}</td><td>{{ lock.lockedUntil || t('admin.notLocked') }}</td><td><button class="secondary-button" @click="unlockIP(lock.ip)"><Unlock :size="15" /> {{ t('admin.unlock') }}</button></td></tr></tbody></table><div v-if="!ipLocks.length" class="empty-state compact-empty"><Unlock :size="26" /><span>{{ t('admin.noLocks') }}</span></div></div><div><h3>{{ t('admin.userLocks') }}</h3><table class="file-table"><thead><tr><th>{{ t('admin.user') }}</th><th>{{ t('admin.failedCount') }}</th><th>{{ t('admin.lockedUntil') }}</th><th></th></tr></thead><tbody><tr v-for="lock in userLocks" :key="lock.id"><td>{{ lock.username }}</td><td>{{ lock.failedAttempts }}</td><td>{{ lock.lockedUntil || t('admin.notLocked') }}</td><td><button class="secondary-button" @click="unlockUser(lock.id)"><Unlock :size="15" /> {{ t('admin.unlock') }}</button></td></tr></tbody></table><div v-if="!userLocks.length" class="empty-state compact-empty"><Unlock :size="26" /><span>{{ t('admin.noLocks') }}</span></div></div></div></div>
        </div>

        <div v-show="activeTab === 'system'">
          <div class="form-panel"><div class="panel-heading"><div><p class="eyebrow">{{ t('admin.tabSystem') }}</p><h2>{{ t('admin.tabSystem') }}</h2></div><button class="secondary-button" :disabled="settingsSaving" @click="saveSettings"><Save :size="16" /> {{ t('admin.saveSettings') }}</button></div><div class="security-grid"><label>{{ t('admin.logRetentionDays') }}<input v-model.number="settings.logRetentionDays" type="number" min="0" /><span>{{ t('common.days') }}</span></label><label>{{ t('admin.uploadRateLimit') }}<input v-model.number="settings.uploadRateLimit" type="number" min="0" step="1" /><span>{{ t('admin.uploadRateLimitCopy') }}</span></label><label class="check-label"><input v-model="settings.registerEnabled" type="checkbox" /> {{ t('admin.registerEnabled') }}<span class="field-hint">{{ t('admin.registerEnabledCopy') }}</span></label></div><p class="muted">{{ t('admin.logRetentionCopy') }}</p></div>
        </div>

        <BrandFooter />
      </section>
    </section>

    <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate = false"><section class="modal-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ t('admin.newAccount') }}</p><h2>{{ t('admin.createHeading') }}</h2></div><button class="icon-button" :title="t('common.close')" @click="showCreate = false"><X :size="18" /></button></div><form class="admin-form" @submit.prevent="createUser"><label>{{ t('login.username') }}<input v-model.trim="createForm.username" required autofocus /></label><label>{{ t('admin.initialPassword') }}<input v-model="createForm.password" type="password" required /><span class="field-hint">{{ t('password.policy', settings) }}</span></label><label>{{ t('admin.role') }}<select v-model="createForm.role"><option value="user">{{ t('admin.userRole') }}</option><option value="admin">{{ t('admin.adminRole') }}</option></select></label><label>{{ t('admin.quotaGB') }}<input v-model.number="createForm.quotaGB" type="number" min="1" required /></label><button class="primary-button submit-button" :disabled="saving"><UserPlus :size="16" /> {{ t('admin.createAccount') }}</button></form></section></div>

    <div v-if="editing" class="modal-backdrop" @click.self="editing = null"><section class="modal-panel edit-modal" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ t('admin.editAccount') }}</p><h2>{{ editing.username }}</h2></div><button class="icon-button" :title="t('common.close')" @click="editing = null"><X :size="18" /></button></div><form class="admin-form" @submit.prevent="updateUser"><label>{{ t('admin.role') }}<select v-model="editForm.role"><option value="user">{{ t('admin.userRole') }}</option><option value="admin">{{ t('admin.adminRole') }}</option></select></label><label>{{ t('admin.quotaGB') }}<input v-model.number="editForm.quotaGB" type="number" min="1" required /></label><label>{{ t('admin.resetPassword') }}<input v-model="editForm.password" type="password" :placeholder="t('admin.passwordUnchanged')" /><span class="field-hint">{{ t('password.policy', settings) }}</span></label><label class="check-label"><input v-model="editForm.disabled" type="checkbox" /> {{ t('admin.disableAccount') }}</label><div class="user-security-form"><label class="check-label"><input v-model="editForm.totpEnabled" type="checkbox" /> {{ t('admin.totpEnabled') }}</label><label class="check-label"><input v-model="editForm.totpReenroll" type="checkbox" /> {{ t('admin.totpReenroll') }}</label><label class="check-label"><input v-model="editForm.ipAclEnabled" type="checkbox" /> {{ t('admin.ipAclEnabled') }}</label><label class="security-whitelist">{{ t('admin.ipWhitelist') }}<input v-model="editForm.ipWhitelist" :placeholder="t('admin.ipWhitelistPlaceholder')" /></label></div><button class="primary-button submit-button" :disabled="saving"><Save :size="16" /> {{ t('admin.saveChanges') }}</button></form></section></div>
  </main>
</template>

<script setup>
// AdminView ä½¿ç”¨å·¦ä¾§é¡µç­¾å¯¼èˆªç»„ç»‡å…¨éƒ¨ç®¡ç†é¢æ¿ï¼ˆæ¦‚è§ˆ/ç”¨æˆ·/å®‰å…¨/å“ç‰Œ/é”å®š/ç³»ç»Ÿï¼‰ï¼Œç”¨æˆ·ç¼–è¾‘ä¸Žæ–°å»ºä¸ºå±…ä¸­å¼¹çª—ã€‚
// AdminView organizes admin panels with a left tab navigation (overview/users/security/branding/locks/system) and centered modals for user create/edit.
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { api, clearSession } from '../api'
import { applyTheme, brand, DEFAULT_THEME_COLOR, isThemeColor, loadBrand, normalizeThemeColor } from '../brand'
import BrandFooter from '../components/BrandFooter.vue'
import BrandLogo from '../components/BrandLogo.vue'
import LanguageSelect from '../components/LanguageSelect.vue'
import { currentLocale, setLocale, systemLocale, t } from '../i18n'
import { Files, FolderOpen, HardDrive, KeyRound, LayoutDashboard, LoaderCircle, Lock, LogOut, Palette, Pencil, RefreshCw, Save, ScrollText, Search, Settings, Share2, Shield, Trash2, Unlock, UserPlus, Users, X } from 'lucide-vue-next'

const router = useRouter(); const route = useRoute(); const sessionUser = ref(JSON.parse(localStorage.getItem('filebox_user') || '{}')); const users = ref([]); const total = ref(0); const stats = ref({}); const ipLocks = ref([]); const userLocks = ref([]); const searchInput = ref(''); const loading = ref(false); const saving = ref(false); const settingsSaving = ref(false); const error = ref(''); const notice = ref(''); const showCreate = ref(false); const editing = ref(null)
// tabs å®šä¹‰å·¦ä¾§èœå•ï¼›activeTab æ”¯æŒ ?tab= æ·±é“¾ä¸Žåˆ·æ–°ä¿æŒã€‚
// tabs defines the left menu; activeTab is restored from the ?tab= query on reload.
const tabs = [
  { key: 'overview', label: 'admin.tabOverview', icon: LayoutDashboard },
  { key: 'users', label: 'admin.tabUsers', icon: Users },
  { key: 'security', label: 'admin.tabSecurity', icon: Lock },
  { key: 'brand', label: 'admin.tabBrand', icon: Palette },
  { key: 'locks', label: 'admin.tabLocks', icon: Shield },
  { key: 'system', label: 'admin.tabSystem', icon: Settings }
]
const validTabs = new Set(tabs.map(tab => tab.key))
const activeTab = ref(validTabs.has(route.query.tab) ? route.query.tab : 'overview')
function switchTab(key) { activeTab.value = key; router.replace({ query: { ...route.query, tab: key } }) }
function openCreate() { showCreate.value = true }
const createForm = reactive({ username: '', password: '', role: 'user', quotaGB: 100 }); const editForm = reactive({ role: 'user', quotaGB: 100, password: '', disabled: false, totpEnabled: false, totpReenroll: false, ipAclEnabled: false, ipWhitelist: '' }); const settings = reactive({ logRetentionDays: 30, defaultLang: 'zh-CN', themeColor: DEFAULT_THEME_COLOR, passwordMinLength: 8, passwordComplexity: 3, ipLockWindowMinutes: 10, ipLockThreshold: 50, ipAutoUnlockEnabled: true, ipUnlockMinutes: 30, registerEnabled: false, uploadRateLimit: 0 })
const brandSaving = ref(false); const brandForm = reactive({ siteTitle: '', siteDescription: '', icpText: '', policeText: '', copyrightText: '', themeColor: DEFAULT_THEME_COLOR }); const brandClears = reactive({ siteTitle: false, siteDescription: false, icpText: false, policeText: false, copyrightText: false }); const brandVersion = ref(Date.now()); const themeColorPicker = ref(DEFAULT_THEME_COLOR); const themeColorInvalid = computed(() => !isThemeColor(brandForm.themeColor))
const brandAssetFields = reactive([{ key: 'favicon', labelKey: 'admin.favicon', accept: '.ico,.png,.svg', hasCustom: false, file: null, pendingRemove: false, preview: '/brand/favicon' }, { key: 'loginLogo', labelKey: 'admin.loginLogo', accept: '.png,.jpg,.svg', hasCustom: false, file: null, pendingRemove: false, preview: '/brand/login-logo' }, { key: 'mainLogo', labelKey: 'admin.mainLogo', accept: '.png,.jpg,.svg', hasCustom: false, file: null, pendingRemove: false, preview: '/brand/main-logo' }])
async function loadUsers() { loading.value = true; try { const body = await api(`/api/admin/users?page=1&pageSize=100&keyword=${encodeURIComponent(searchInput.value)}`); users.value = body.data.items; total.value = body.data.total } catch (err) { error.value = err.message } finally { loading.value = false } }
async function loadStats() { try { stats.value = (await api('/api/admin/stats')).data } catch (err) { error.value = err.message } }
async function loadSettings() { try { const data = (await api('/api/admin/settings')).data; Object.assign(settings, data, { uploadRateLimit: Math.round((data.uploadRateLimit || 0) / 1024) }) } catch (err) { error.value = err.message } }
function loadAll() { loadUsers(); loadStats(); loadSettings(); loadLocks() }
async function loadLocks() { try { const body = await api('/api/admin/locks'); ipLocks.value = body.data.ipLocks; userLocks.value = body.data.userLocks } catch (err) { error.value = err.message } }
function loadBrandSettings() { Object.assign(brandForm, { siteTitle: brand.siteTitle, siteDescription: brand.siteDescription, icpText: brand.icpText, policeText: brand.policeText, copyrightText: brand.copyrightText || '', themeColor: brand.themeColor }); themeColorPicker.value = normalizeThemeColor(brand.themeColor); Object.assign(brandClears, { siteTitle: false, siteDescription: false, icpText: false, policeText: false, copyrightText: false }); const custom = { favicon: brand.hasFavicon, loginLogo: brand.hasLoginLogo, mainLogo: brand.hasMainLogo }; brandAssetFields.forEach(asset => { asset.hasCustom = custom[asset.key]; asset.file = null; asset.pendingRemove = false; asset.preview = `${asset.preview.split('?')[0]}?v=${brandVersion.value}` }) }
function clearText(key) { brandForm[key] = ''; brandClears[key] = true }
function selectThemeColor(event) { brandForm.themeColor = event.target.value }
function resetThemeColor() { brandForm.themeColor = ''; themeColorPicker.value = DEFAULT_THEME_COLOR }
function selectBrandFile(asset, event) { const file = event.target.files?.[0]; if (!file) return; asset.file = file; asset.pendingRemove = false; asset.hasCustom = true; asset.preview = URL.createObjectURL(file); event.target.value = '' }
function removeBrandFile(asset) { asset.file = null; asset.pendingRemove = true; asset.hasCustom = false; asset.preview = `${asset.preview.split('?')[0]}?v=${brandVersion.value}` }
async function saveSettings() { settingsSaving.value = true; error.value = ''; try { const payload = { ...settings, uploadRateLimit: Math.max(0, Number(settings.uploadRateLimit) || 0) * 1024 }; const body = await api('/api/admin/settings', { method: 'PUT', body: JSON.stringify(payload) }); Object.assign(settings, body.data, { uploadRateLimit: Math.round((body.data.uploadRateLimit || 0) / 1024) }); systemLocale.value = settings.defaultLang; if (!sessionUser.value.language && !localStorage.getItem('filebox_locale')) setLocale(''); notice.value = t('notice.settingsSaved') } catch (err) { error.value = err.message } finally { settingsSaving.value = false } }
async function saveThemeColor() { const payload = { ...settings, themeColor: brandForm.themeColor, uploadRateLimit: Math.max(0, Number(settings.uploadRateLimit) || 0) * 1024 }; const body = await api('/api/admin/settings', { method: 'PUT', body: JSON.stringify(payload) }); Object.assign(settings, body.data, { uploadRateLimit: Math.round((body.data.uploadRateLimit || 0) / 1024) }); applyTheme(brandForm.themeColor) }
async function saveBrand() { if (themeColorInvalid.value) return; brandSaving.value = true; error.value = ''; const form = new FormData(); const clearKeys = { siteTitle: 'clearTitle', siteDescription: 'clearDescription', icpText: 'clearIcp', policeText: 'clearPolice', copyrightText: 'clearCopyright' }; ['siteTitle', 'siteDescription', 'icpText', 'policeText', 'copyrightText'].forEach(key => { if (brandForm[key]) form.append(key, brandForm[key]); if (brandClears[key]) form.append(clearKeys[key], 'true') }); brandAssetFields.forEach(asset => { const field = asset.key === 'loginLogo' ? 'loginLogo' : asset.key === 'mainLogo' ? 'mainLogo' : 'favicon'; if (asset.file) form.append(field, asset.file); else if (asset.pendingRemove) form.append(`remove${field[0].toUpperCase()}${field.slice(1)}`, 'true') }); try { const body = await api('/api/admin/brand', { method: 'PUT', body: form }); await saveThemeColor(); Object.assign(brand, body.data); await loadBrand(); brandVersion.value = Date.now(); loadBrandSettings(); notice.value = t('notice.brandSaved') } catch (err) { error.value = err.message } finally { brandSaving.value = false } }
async function resetBrand() { if (!window.confirm(t('confirm.resetBrand'))) return; brandSaving.value = true; try { const body = await api('/api/admin/brand?reset=true', { method: 'PUT', body: new FormData() }); brandForm.themeColor = ''; await saveThemeColor(); Object.assign(brand, body.data); await loadBrand(); brandVersion.value = Date.now(); loadBrandSettings(); notice.value = t('notice.brandReset') } catch (err) { error.value = err.message } finally { brandSaving.value = false } }
async function createUser() { saving.value = true; error.value = ''; try { await api('/api/admin/users', { method: 'POST', body: JSON.stringify({ username: createForm.username, password: createForm.password, role: createForm.role, quotaBytes: createForm.quotaGB * 1024 ** 3 }) }); notice.value = t('notice.userCreated'); showCreate.value = false; Object.assign(createForm, { username: '', password: '', role: 'user', quotaGB: 100 }); loadAll() } catch (err) { error.value = err.message } finally { saving.value = false } }
function edit(item) { editing.value = item; Object.assign(editForm, { role: item.role, quotaGB: Math.round(item.quotaBytes / 1024 ** 3), password: '', disabled: item.disabled, totpEnabled: item.totpEnabled, totpReenroll: false, ipAclEnabled: item.ipAclEnabled, ipWhitelist: item.ipWhitelist || '' }) }
async function updateUser() { saving.value = true; error.value = ''; try { await api(`/api/admin/users/${editing.value.id}`, { method: 'PUT', body: JSON.stringify({ role: editForm.role, quotaBytes: editForm.quotaGB * 1024 ** 3, password: editForm.password, disabled: editForm.disabled }) }); await api(`/api/admin/users/${editing.value.id}/totp`, { method: 'PUT', body: JSON.stringify({ enabled: editForm.totpEnabled, reenroll: editForm.totpReenroll }) }); await api(`/api/admin/users/${editing.value.id}/ip-acl`, { method: 'PUT', body: JSON.stringify({ enabled: editForm.ipAclEnabled, whitelist: editForm.ipWhitelist }) }); notice.value = t('notice.userUpdated'); editing.value = null; loadAll() } catch (err) { error.value = err.message } finally { saving.value = false } }
async function unlockIP(ip) { try { await api(`/api/admin/locks/ip/${encodeURIComponent(ip)}`, { method: 'DELETE' }); notice.value = t('notice.lockReleased'); loadLocks() } catch (err) { error.value = err.message } }
async function unlockUser(id) { try { await api(`/api/admin/locks/user/${id}`, { method: 'DELETE' }); notice.value = t('notice.lockReleased'); loadLocks() } catch (err) { error.value = err.message } }
async function remove(item) { if (!window.confirm(t('confirm.deleteUser', { name: item.username }))) return; try { await api(`/api/admin/users/${item.id}`, { method: 'DELETE' }); notice.value = t('notice.userDeleted'); loadAll() } catch (err) { error.value = err.message } }
async function logout() { try { await api('/api/auth/logout', { method: 'POST' }) } finally { clearSession(); router.push('/login') } }
function formatBytes(bytes = 0) { if (bytes < 1024) return `${bytes} B`; const units = ['KB', 'MB', 'GB', 'TB']; let value = bytes; let unit = -1; do { value /= 1024; unit++ } while (value >= 1024 && unit < units.length - 1); return `${value.toFixed(value >= 10 ? 0 : 1)} ${units[unit]}` }
function formatDate(value) { return value ? new Date(value).toLocaleDateString(currentLocale.value) : '-' }
watch(() => brandForm.themeColor, value => { if (isThemeColor(value)) themeColorPicker.value = value ? normalizeThemeColor(value) : DEFAULT_THEME_COLOR })
onMounted(async () => { loadAll(); await loadBrand(); loadBrandSettings() })
</script>

