@media (max-width: 900px) { .admin-layout { flex-direction: column; } .admin-sidebar { position: static; flex-direction: row; flex-wrap: wrap; flex-basis: auto; } }
.disk-stat strong { margin-top: 11px; font-size: 18px; white-space: nowrap; }
.disk-stat-meta { margin-top: 4px; color: #6b7c93; font-size: 12px; }
.disk-progress { height: 6px; margin-top: 10px; }
